-- Dữ liệu ban đầu cho ứng dụng Báo giá: cài đặt công ty và máy LW230H (chạy sau schema.sql)
insert into public.quote_settings (id, data) values ('company', $q${"companyName": "CÔNG TY TNHH KHOA HỌC VÀ CÔNG NGHỆ SATICUS", "header": "VietNam\nHCM Office: A13, Cao Thi Chinh, Phu Thuan Ward, Dist. 7, HCMC, Viet Nam\nHa Noi Office: B45 – 13, Geleximco New Urban Area, Le Trong Tan Street, Ha Dong District, Hanoi City, Viet Nam\nTel: 0909052296-Email: salomonhuynh@saticus.com-Website: www.saticus.com\n\nIndonesia\nPT. SatiCus Lab Dan Pilot Equipment\nBogor Office: No.6 Blok C, Plaza Niaga, Jl. MH. Thamrin No.1, Citaringgul, Babakan Madang, Bogor Regency, West Java\nTel: 00 62 81113805721-Email: salomonhuynh@saticus.id-Website: www.saticus.id", "intro": "CÔNG TY TNHH KHOA HỌC VÀ CÔNG NGHỆ SATICUS xin chân thành cảm ơn sự quan tâm và tin tưởng của Quý khách hàng đến sản phẩm và dịch vụ của chúng tôi. Chúng tôi xin trân trọng gửi đến Quý khách Bản chào giá theo yêu cầu như sau:", "signTitle": "", "signName": "", "vat": 8, "terms": "Giá trên là giá giao hàng tại khách hàng, đã bao gồm các phí vận chuyển trong nước và quốc tế, thuế nhập khẩu.\nGiá trên đã bao gồm VAT {VAT}%\nChất lượng hàng hoá: mới 100% theo đúng tiêu chuẩn nhà sản xuất.\nĐiều khoản thanh toán:\n- Thanh toán đợt 1: 30% giá trị hợp đồng trong vòng 15-20 ngày kể từ ngày ký hợp đồng\n- Thanh toán đợt 2: 50% giá trị hợp đồng trong vòng 15-20 ngày sau khi hoàn thành nghiệm thu FAT và có thông báo giá giao hàng\n- Thanh toán đợt 3: 20% gía trị hợp đồng trong vòng 15-20 ngày sau khi hoàn thành nghiệm thu SAT\nBảo hành: 24 tháng\nBảo trì, bảo dưỡng: hỗ trợ bảo trì, bảo dưỡng sau thời thời gian bảo hành\nThời gian giao hàng: 8-12 tuần kể từ ngày nhận cọc, thời gian chậm nhất hoàn thành hợp đồng là 20 tuần\nBáo giá có giá trị trong vòng 60 ngày kể từ ngày báo giá.\nĐồng ý bảo đảm thực hiện hợp đồng và bảo đảm bảo hành thương thảo chi tiết trong hợp đồng."}$q$::jsonb)
on conflict (id) do update set data = excluded.data;

insert into public.quote_products (id, name, model, code, maker, origin, sections, scope) values
('lw230h', $q$Máy Rửa Dụng Cụ$q$, $q$LW230H$q$, $q$$q$, $q$Eurping$q$, $q$Trung Quốc$q$, $q$[{"title": "Cấu Hình Giỏ Rửa Linh Hoạt:", "lines": ["Cho phép lắp đồng thời 4 giỏ dạng module, có thể kết hợp linh hoạt để phù hợp với nhiều loại dụng cụ như: bình định mức, lọ mẫu tự động, lọ headspace, pipet, ống nghiệm, bình tam giác (Erlenmeyer), bình cầu đáy tròn, chai thuốc thử, ống đong, v.v."]}, {"title": "Buồng rửa:", "lines": ["Dung tích 223L. Giỏ hai tầng có thể rửa đồng thời 128 bình định mức 100 mL hoặc 600 lọ tiêm sắc ký dung tích 2 mL trong một chu trình."]}, {"title": "Cấu trúc thiết bị:", "lines": ["Vỏ máy làm bằng thép không gỉ 304, buồng rửa bằng thép không gỉ 316L. Buồng rửa dung tích 223L được gia công liền khối, không có mối hàn."]}, {"title": "Hệ thống điều khiển:", "lines": ["Hệ thống điều khiển: Ứng dụng công nghệ vi xử lý (không dùng PLC), trang bị màn hình cảm ứng LCD OLED màu 7 inch. Tích hợp sẵn 30 chương trình rửa tiêu chuẩn và 120 chương trình do người dùng tùy chỉnh.", "Các quyền vận hành:", "Quyền cấp 1: Quyền vận hành (Operator): Chỉ có thể gọi các chương trình đã được thiết lập sẵn để làm sạch các thùng chứa cần vệ sinh.", "Quyền cấp 2: Quyền debug: Có thể gọi các chương trình đã thiết lập sẵn để làm sạch các thùng chứa cần vệ sinh, điều chỉnh các thông số vận hành của máy rửa chai để hoàn tất việc hiệu chỉnh, thay đổi tên chương trình làm sạch, v.v.", "Quyền cấp 3: Quyền quản lý (Manager): Có thể gọi các chương trình đã thiết lập sẵn để làm sạch các thùng chứa cần vệ sinh, điều chỉnh các thông số vận hành của máy rửa chai để hoàn tất việc hiệu chỉnh chương trình, thay đổi tên chương trình làm sạch, xem hồ sơ/lịch sử làm sạch, trạng thái hộp đen và cổng, chỉnh sửa thời gian, vận hành từng bước (single-step) của máy rửa chai, v.v.", "Quyền cấp 4: Quyền siêu vận hành (Super): Sau khi truy cập quyền này, hệ thống sẽ được mở cho tất cả các thao tác vận hành.", "Gia nhiệt nước: Cài đặt mặc định là 45 phút, và thông thường nhiệt độ nước có thể đạt đến mức cài đặt trong vòng 45 phút.", "Thời gian xả nước: Cài đặt mặc định là 90 giây, và thông thường việc xả nước có thể hoàn tất trong vòng 90 giây. (Nếu ống xả được kéo dài hoặc đầu vào nước thải quá cao, thời gian xả có thể được kéo dài)", "Bảo vệ nhiệt độ cửa: Khi nhiệt độ nước vượt quá nhiệt độ cài đặt, cửa sẽ không thể mở. (Chức năng này không áp dụng sau khi thoát khỏi chương trình đang chạy)", "Kiểm tra độ dẫn điện: Sau khi bật, màn hình sẽ hiển thị dữ liệu độ dẫn điện của hai lần đo trước và sau khi làm sạch.", "Tự động in: Sau khi kết nối máy in và hoàn tất quá trình làm sạch, dữ liệu làm sạch có thể được in tự động.", "Thời gian xả rửa (Flush): Thời gian để xả rửa khoang bên trong. Diễn ra giữa giai đoạn rửa sơ bộ và làm sạch trung hòa, cũng như giữa làm sạch trung hòa và tráng rửa.", "Phương thức đăng nhập: Có thể thay đổi phương thức đăng nhập khi khởi động, lựa chọn đăng nhập bằng vân tay hoặc mật khẩu.", "Các dạng cảnh báo:", "- Không đủ nước cấp", "- Cửa đóng không đúng cách", "- Kiểm tra phát hiện rò rỉ", "- Tràn nước"]}, {"title": "Hiển thị & ghi nhận dữ liệu:", "lines": ["Các thông số như lưu lượng nước đầu vào, chương trình rửa, giai đoạn rửa, thời gian, nhiệt độ và áp suất đường ống được hiển thị theo thời gian thực.", "Thiết bị tự động ghi lại trạng thái hoạt động của từng linh kiện điện trong suốt quá trình vận hành."]}, {"title": "Hệ thống tuần hoàn:", "lines": ["Bơm tuần hoàn điều khiển bằng biến tần với chức năng khởi động mềm, dải lưu lượng từ 0–600 L/phút. Cảm biến áp suất đường ống giám sát áp suất đường ống chính theo thời gian thực."]}, {"title": "Hệ thống an toàn:", "lines": ["Trang bị khóa an toàn điện tử, công nghệ đóng/mở cửa điện EULA; người vận hành có thể thiết lập nhiệt độ giới hạn để mở cửa."]}, {"title": "Bảo vệ quá nhiệt:", "lines": ["Bảo vệ quá nhiệt gia nhiệt nước", "Bảo vệ quá nhiệt khí nóng", "Bảo vệ quá nhiệt bơm nước", "Bảo vệ quá nhiệt quạt"]}, {"title": "Hệ thống lọc đa tầng:", "lines": ["Ngăn chặn cặn bẩn xâm nhập vào đường ống, tránh gây tắc nghẽn."]}, {"title": "Hệ thống sấy:", "lines": ["Hệ thống sấy HEPA sử dụng quạt nén lưu lượng cao, lưu lượng khí nóng tuần hoàn đạt 150 m³/h.", "Khí khô được dẫn vào giỏ rửa giúp làm khô hoàn toàn cả bên trong và bên ngoài dụng cụ thủy tinh.", "- Nhiệt độ điều chỉnh: từ nhiệt độ phòng đến 120°C", "- Thời gian sấy: 0–300 phút", "Hệ thống trao đổi nhiệt phun kép sử dụng công nghệ ngưng tụ tiết kiệm nước EU-W để ngưng tụ hơi và tự động xả nước làm mát. Bộ ngưng tụ hơi chế tạo từ thép không gỉ chất lượng cao, có khả năng làm nguội dụng cụ trước khi kết thúc chu trình."]}, {"title": "Hệ thống đường ống:", "lines": ["Tích hợp bơm tăng áp nước tinh khiết bên trong thiết bị.", "Áp dụng phương thức cấp nước hồi lưu (back water supply) để cấp nước cho giỏ rửa.", "Giỏ rửa thiết kế dạng module FL-EXCH, mỗi nửa module có thể thay thế linh hoạt."]}, {"title": "Độ chính xác:", "lines": ["- Độ chính xác nhiệt độ: ± 3°C", "- Độ chính xác thời gian: ± 10 giây", "- Độ chính xác bơm hoá chất: ± 5%"]}, {"title": "Hiệu năng:", "lines": ["- Đảm bảo tráng sạch toàn bộ bề mặt bên trong và bên ngoài của chai.", "- Loại bỏ hiệu quả các hạt, bụi bẩn và chất nhiễm bẩn nhìn thấy bằng mắt thường trên chai bằng phương pháp tráng sạch.", "- Hệ thống phải đạt yêu cầu về kiểm tra Riboflavin.", "- Chênh lệch độ dẫn điện và TOC của nước tinh khiết ban đầu và nước tinh khiết sau khi tráng dụng cụ đã rửa: TOC ≤ 0,5 mg/L; Độ dẫn điện (20°C) ≤ 1,5 μS/cm."]}, {"title": "Thiết kế:", "lines": ["- Kim phun rửa phải được định tâm và không được tiếp xúc hoặc gây hư hỏng chai.", "- Thiết kế thiết bị phải hạn chế tối đa nguy cơ phát sinh hoặc đưa tiểu phân hay chất lạ vào chai trong quá trình làm sạch và sấy.", "- Hệ thống phải có HMI để điều khiển chu trình, hiển thị trạng thái, cảnh báo, thông báo và chức năng reset.", "- Hệ thống thoát nước phải phù hợp và ngăn dòng chảy ngược.", "- Bề mặt bên ngoài phải nhẵn, không có điểm giữ bẩn và dễ vệ sinh.", "- Hệ thống phải có chức năng sấy khô dụng cụ sau khi rửa, đảm bảo dụng cụ đạt trạng thái khô phù hợp cho mục đích sử dụng."]}, {"title": "Tính năng an toàn:", "lines": ["- Có nút dừng khẩn cấp. Khi kích hoạt, tất cả bộ phận chuyển động phải dừng và các nguồn năng lượng nguy hiểm phải được loại bỏ hoặc kiểm soát.", "- Sau khi kích hoạt cơ chế khóa an toàn, phải thực hiện thao tác reset trước khi thiết bị có thể vận hành trở lại.", "- Hệ thống phải duy trì điều kiện vệ sinh, không còn cặn bẩn, tồn dư hóa chất hoặc nhiễm bẩn sinh học sau mỗi chu trình sử dụng.", "- Không cho phép bỏ qua hoặc vô hiệu hóa cơ chế khóa an toàn trong quá trình vận hành.", "- Hệ thống phải cảnh báo khi mức hóa chất dưới mức cho phép.", "- Có sensor theo dõi chuyển động của cánh phun, và cảnh báo khi cánh phun không hoạt động.", "- Hệ thống phải có chế độ tự làm sạch hoặc chu trình tráng rửa tự động để hỗ trợ việc bảo trì và vệ sinh thiết bị.", "- Phải có chỉ báo rõ ràng (đèn báo hoặc thông báo trên màn hình) để xác nhận khi chu trình bảo trì đã hoàn tất và máy rửa đã sẵn sàng cho lần sử dụng tiếp theo."]}, {"title": "Điều kiện lắp đặt:", "lines": ["- Nguồn điện: 350 – 415V", "- Nhiệt độ: 0°C – 40°C", "- Độ ẩm: 70% RH"]}, {"title": "Thông số kỹ thuật:", "lines": ["Aptomat nguồn: 32A", "Bơm cấp hóa chất tẩy rửa: 2", "Bơm nước tinh khiết đầu vào: 1", "Bơm xả: 1", "Kích thước trong: 546 × 573 × 762 mm (223L)", "Kích thước ngoài: 670 × 758 × 1394 mm", "Điện áp & công suất: 220V, 5 kW", "Khối lượng: 210 kg", "Chứng nhận: Sản phẩm đạt chứng nhận CE; nhà sản xuất đạt các tiêu chuẩn ISO 9001, ISO 14001 và ISO 45001.", "Thông số TOC ≤ 0,5mg/L:", "- Tiến hành đánh giá thông số này thông qua việc so sánh sự chênh lệch giữa nước tráng cuối cùng và nước nguồn đầu vào, nhằm xác định khả năng đáp ứng của hệ thống đối với yêu cầu kỹ thuật đề ra.", "- Nội dung sẽ được thực hiện trong PQ", "Thông số độ dẫn điện (20°C) ≤ 1,5 μS/cm:", "- Tiến hành đánh giá thông số này thông qua việc so sánh sự chênh lệch giữa nước tráng cuối cùng và nước nguồn đầu vào, nhằm xác định khả năng đáp ứng của hệ thống đối với yêu cầu kỹ thuật đề ra.", "- Nội dung sẽ được thực hiện trong PQ", "- Bên cạnh việc thực hiện trong PQ, máy rửa được trang bị thêm cảm biến đo độ dẫn điện, thực hiện đo trước và sau quá trình làm sạch mỗi mẻ rửa. Kết quả đo sẽ được hiển thị trên màn hình điều khiển ngay khi chu trình rửa hoàn tất.", "- Việc kiểm tra độ dẫn điện tại nước tráng cuối cùng nhằm mục đích xác nhận và chứng minh dụng cụ đã được làm sạch đạt yêu cầu, đồng thời cung cấp thông số cụ thể làm bằng chứng kỹ thuật cho quá trình vệ sinh cho mỗi mẻ rửa hằng ngày.", "Máy có trang bị sensor theo dõi áp suất nước:", "- Áp lực phun là một trong những tiêu chí quan trọng để đánh giá hiệu quả làm sạch của dụng cụ rửa.", "- Do đó, máy được trang bị cảm biến (sensor) theo dõi áp suất nước nhằm đảm bảo nước luôn đạt áp suất phù hợp để hệ thống hoạt động ổn định, tránh tình trạng thiếu nước hoặc suy giảm áp lực phun tại bất kỳ vị trí rửa nào trong buồng rửa", "- Trong trường hợp áp suất phun không hoạt động ổn định thiếu áp, hoặc suy giảm áp lực phun, hệ thống sẽ tự động phát tín hiệu cảnh báo, hiển thị thông báo lỗi và ngừng hoạt động máy, nhằm đảm bảo chất lượng và an toàn của quá trình rửa.", "Máy có trang bị sensor theo dõi chuyển động của cánh phun:", "- Cảm biến theo dõi chuyển động của cánh phun được tích hợp nhằm đảm bảo cánh phun hoạt động bình thường, cánh phun quay đều, qua đó đảm bảo nước được phân bố đồng đều đến toàn bộ buồng rửa.", "- Trong trường hợp chuyển động của cánh phun không hoạt động ổn định, hệ thống sẽ tự động phát tín hiệu cảnh báo, hiển thị thông báo lỗi và ngừng hoạt động nhằm đảm bảo chất lượng và an toàn của quá trình rửa."]}]$q$::jsonb, $q$[{"code": "", "text": "Máy Rửa Dụng Cụ\nModel: LW230\nNSX: Eurping\nXuất xứ: Trung Quốc", "qty": "1"}, {"code": "", "text": "Thực hiện lắp đặt (đã bao gồm điện 3 pha)", "qty": "1"}, {"code": "", "text": "Tài liệu và thực hiện IQ, OQ, PQ.", "qty": "1"}, {"code": "", "text": "Tài liệu CO, CQ", "qty": "1"}, {"code": "", "text": "Hướng dẫn sử dụng", "qty": "1"}, {"code": "", "text": "Phụ Kiện Rửa:", "qty": ""}, {"code": "PLYT-66", "text": "Giỏ module phun rửa chai: \nKích thước chai phù hợp: 10–50 mL\nỨng dụng: Dùng để rửa chai nắp xanh, bình tam giác (Erlenmeyer), bình định mức, bình tam giác và các loại bình khác. Được trang bị 33 giá đỡ chai inox dạng ba cánh (three-petal) và giá đỡ dạng chữ thập.\nĐầu phun: Φ3.2 × cao 110 mm × 66 đầu\nThiết kế: Tối ưu theo bình định mức 25 mL; mỗi module có thể rửa 66 bình định mức.", "qty": "1"}, {"code": "PLYT-50", "text": "Giỏ module phun rửa chai:\nKích thước chai phù hợp: 10–100 mL\nỨng dụng: Dùng để rửa chai nắp xanh, bình tam giác (Erlenmeyer), bình định mức, bình tam giác và các loại bình khác. Được trang bị giá đỡ chai inox dạng ba cánh (three-petal) và giá đỡ dạng chữ thập.\nĐầu phun: Φ3.2 × cao 110 mm × 50 đầu\nThiết kế: Tối ưu theo bình định mức 50 mL; mỗi module có thể rửa 50 bình định mức.", "qty": "1"}, {"code": "PLYT-32", "text": "Giỏ module phun rửa chai:\nKích thước chai phù hợp: 50–250 mL\nỨng dụng: Dùng để rửa chai nắp xanh, bình tam giác (Erlenmeyer), bình định mức, bình tam giác và các loại bình khác. Được trang bị 16 giá đỡ chai inox dạng ba cánh (three-petal) và giá đỡ dạng chữ thập.\nĐầu phun: Φ4 × cao 165 mm × 32 đầu\nThiết kế: Tối ưu theo bình định mức 100 mL; mỗi module có thể rửa 32 bình định mức.", "qty": "3"}, {"code": "PLYT-21", "text": "Giỏ module phun rửa chai:\nKích thước chai phù hợp: 50–250 mL\nỨng dụng: Dùng để rửa chai nắp xanh, bình tam giác (Erlenmeyer), bình định mức, bình tam giác và các loại bình khác. Được trang bị giá đỡ chai inox dạng ba cánh (three-petal) và giá đỡ dạng chữ thập.\nĐầu phun: Φ4.6 × cao 165 mm × 21 đầu\nThiết kế: Tối ưu theo bình định mức 250 mL; mỗi module có thể rửa 21 bình định mức.", "qty": "3"}, {"code": "PL-150", "text": "Giỏ module phun rửa chai: \nKích thước chai phù hợp: 2 mL\nỨng dụng: Dùng để rửa lọ tiêm mẫu sắc ký (chromatographic vial)\nĐầu phun: Φ2 × cao 45 mm × 150 đầu", "qty": "2"}, {"code": "SC-01", "text": "Khung làm sạch phía trên, không có tay phun, dùng để đặt giỏ làm sạch mô-đun.", "qty": "1"}, {"code": "XC-03", "text": "Khung làm sạch phía dưới, không có tay phun, dùng để đặt giỏ làm sạch mô-đun.", "qty": "1"}, {"code": "K-30", "text": "Mô-đun khung rửa 1/2 – 30 vị trí\n• Kích thước bình: đĩa petri đường kính 60～150mm\n• Mỗi mô-đun có thể rửa 30 đĩa petri loại 90mm\n• Hai mô-đun 1/2 tạo thành một tầng của giỏ rửa", "qty": "4"}, {"code": "", "text": "Dung dịch rửa 1 bộ bao gồm:\nRBS A 375 Acidic neutralizing detergent 5L\nRBS A 156 Highly alkaline detergent 5L\nXuất xứ: EU", "qty": "12"}]$q$::jsonb)
